def subset_sum_exists(nums: List[int], target: int) -> bool:
    """Check if there is a subset of nums with sum equal to target."""
    dp = [False] * (target + 1)
    dp[0] = True

    for num in nums:
        for s in range(target, num - 1, -1):
            if dp[s - num]:
                dp[s] = True

    return dp[target]

