def coin_combinations_count(coins: List[int], target: int) -> int:
    """Calculate total number of distinct coin combinations that sum to target."""
    dp = [0] * (target + 1)
    dp[0] = 1

    for coin in coins:
        for amount in range(coin, target + 1):
            dp[amount] += dp[amount - coin]

    return dp[target]

