class RollbackDSU:
    """Union-Find supporting history stack rollbacks."""
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.history: List[Tuple[int, int, bool]] = []

    def find(self, i: int) -> int:
        while self.parent[i] != i:
            i = self.parent[i]
        return i

    def union(self, u: int, v: int) -> bool:
        ru, rv = self.find(u), self.find(v)
        if ru == rv:
            self.history.append((ru, rv, False))
            return False
        if self.rank[ru] < self.rank[rv]:
            ru, rv = rv, ru
        self.parent[rv] = ru
        rank_inc = (self.rank[ru] == self.rank[rv])
        if rank_inc:
            self.rank[ru] += 1
        self.history.append((ru, rv, rank_inc))
        return True

    def rollback(self) -> None:
        if not self.history:
            return
        ru, rv, rank_inc = self.history.pop()
        if ru != rv:
            self.parent[rv] = rv
            if rank_inc:
                self.rank[ru] -= 1

