class SplayMap:
    """Key-value dictionary backed by a splay tree."""
    def __init__(self):
        self.root: Optional[SNode] = None

    def _right_rot(self, node: SNode) -> SNode:
        left = node.left
        assert left is not None
        node.left = left.right
        left.right = node
        return left

    def _left_rot(self, node: SNode) -> SNode:
        right = node.right
        assert right is not None
        node.right = right.left
        right.left = node
        return right

    def insert(self, key: int, val: Any) -> None:
        if not self.root:
            self.root = SNode(key, val)
            return
        curr = self.root
        while True:
            if key < curr.key:
                if not curr.left:
                    curr.left = SNode(key, val)
                    break
                curr = curr.left
            elif key > curr.key:
                if not curr.right:
                    curr.right = SNode(key, val)
                    break
                curr = curr.right
            else:
                curr.val = val
                break

import base64
import hmac
import hashlib
import json
import time
from typing import Dict, Any, Optional

def decode_jwt_hs256(token: str, secret_key: str) -> Optional[Dict[str, Any]]:
    """Decode and verify an HS256 JWT, returning payload or None if invalid/expired."""
    parts = token.split(".")
    if len(parts) != 3:
        return None
    header_b64, payload_b64, sig_b64 = parts

    def pad_b64(s: str) -> bytes:
        return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))

    signing_input = f"{header_b64}.{payload_b64}".encode("utf-8")
    expected_sig = hmac.new(secret_key.encode("utf-8"), signing_input, hashlib.sha256).digest()

    try:
        actual_sig = pad_b64(sig_b64)
        if not hmac.compare_digest(actual_sig, expected_sig):
            return None
        payload = json.loads(pad_b64(payload_b64).decode("utf-8"))
        if "exp" in payload and time.time() > payload["exp"]:
            return None  # Expired
        return payload
    except Exception:
        return None

import base64
from typing import Optional, Tuple

def parse_basic_auth_header(header_value: str) -> Optional[Tuple[str, str]]:
    """Extract (username, password) from 'Basic <base64>' authorization header."""
    if not header_value or not header_value.startswith("Basic "):
        return None
    b64_str = header_value[6:].strip()
    try:
        decoded = base64.b64decode(b64_str).decode("utf-8")
        if ":" not in decoded:
            return None
        username, password = decoded.split(":", 1)
        return username, password
    except Exception:
        return None

