def read_c_string(buffer: bytes, offset: int = 0) -> Tuple[str, int]:
    """Read null-terminated ASCII string from buffer returning (string, next_offset)."""
    null_idx = buffer.find(bytes([0]), offset)
    if null_idx == -1:
