def match_simple_glob(pattern: str, text: str) -> bool:
    """Test if text matches glob pattern supporting '*' and '?' wildcards."""
    regex = "^"
    for char in pattern:
        if char == "*":
            regex += ".*"
        elif char == "?":
            regex += "."
        elif char in ".^$+-()[]{}|\\":
            regex += "\\" + char
        else:
            regex += char
    regex += "$"
    return bool(re.match(regex, text))

