class PartitionedThreadMap:
    """Thread-safe hash map with sharded locks for reduced contention."""
    def __init__(self, num_shards: int = 16):
        self.num_shards = num_shards
        self.shards: List[Dict[str, Any]] = [{} for _ in range(num_shards)]
        self.locks: List[threading.Lock] = [threading.Lock() for _ in range(num_shards)]

    def _shard_idx(self, key: str) -> int:
        return hash(key) % self.num_shards

    def set(self, key: str, val: Any) -> None:
        idx = self._shard_idx(key)
        with self.locks[idx]:
            self.shards[idx][key] = val

    def get(self, key: str) -> Optional[Any]:
        idx = self._shard_idx(key)
        with self.locks[idx]:
            return self.shards[idx].get(key)

from typing import List

def matrix_multiply(a: List[List[float]], b: List[List[float]]) -> List[List[float]]:
    """Multiply two 2D matrices a (M x K) and b (K x N)."""
    rows_a, cols_a = len(a), len(a[0])
    rows_b, cols_b = len(b), len(b[0])
    if cols_a != rows_b:
        raise ValueError(f"Incompatible dimensions: {cols_a} != {rows_b}")
    res = [[0.0] * cols_b for _ in range(rows_a)]
    for i in range(rows_a):
        for k in range(cols_a):
            for j in range(cols_b):
                res[i][j] += a[i][k] * b[k][j]
    return res

from typing import List

def matrix_determinant(matrix: List[List[float]]) -> float:
    """Compute determinant of N x N square matrix via Gaussian elimination."""
    n = len(matrix)
    mat = [row[:] for row in matrix]
    det = 1.0

    for i in range(n):
        pivot = i
        for j in range(i + 1, n):
            if abs(mat[j][i]) > abs(mat[pivot][i]):
                pivot = j
        if pivot != i:
            mat[i], mat[pivot] = mat[pivot], mat[i]
            det *= -1.0
        if abs(mat[i][i]) < 1e-12:
            return 0.0
        det *= mat[i][i]
        for j in range(i + 1, n):
            factor = mat[j][i] / mat[i][i]
            for k in range(i + 1, n):
                mat[j][k] -= factor * mat[i][k]
    return det

from typing import List

def invert_matrix_gauss_jordan(matrix: List[List[float]]) -> List[List[float]]:
    """Invert an N x N invertible matrix using Gauss-Jordan elimination."""
    n = len(matrix)
    aug = [matrix[i] + [1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]

    for i in range(n):
        pivot = max(range(i, n), key=lambda r: abs(aug[r][i]))
        aug[i], aug[pivot] = aug[pivot], aug[i]
        div = aug[i][i]
        if abs(div) < 1e-12:
            raise ValueError("Matrix is singular and non-invertible")
        for j in range(2 * n):
            aug[i][j] /= div
        for r in range(n):
            if r != i:
                f = aug[r][i]
                for c in range(2 * n):
                    aug[r][c] -= f * aug[i][c]
    return [row[n:] for row in aug]

