def n_choose_k(n: int, k: int) -> int:
    """Calculate binomial coefficient n choose k."""
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def n_permute_k(n: int, k: int) -> int:
    """Calculate n P k permutations."""
    if k < 0 or k > n:
