def poisson_pmf(k: int, lam: float) -> float:
    """Compute Poisson probability P(X = k) = (lambda^k * exp(-lambda)) / k!."""
    if k < 0 or lam <= 0:
        raise ValueError("Invalid parameters")
    return (math.pow(lam, k) * math.exp(-lam)) / math.factorial(k)

